public class TaskOutcomeTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static void checkCall(String label, Object expected, java.util.concurrent.Callable<Object> call) {
        Object actual;
        try {
            actual = call.call();
        } catch (Throwable t) {
            actual = t.getClass().getSimpleName();
        }
        check(label, expected, actual);
    }

    public static void main(String[] args) {
        TaskOutcome<Integer, String> ok = TaskOutcome.success(7);
        TaskOutcome<Integer, String> bad = TaskOutcome.failure("boom");

        checkCall("success(7).isSuccess()", true, () -> ok.isSuccess());
        checkCall("success(7).valueOr(-1)", 7, () -> ok.valueOr(-1));
        checkCall("success(7).errorOr(none)", "none", () -> ok.errorOr("none"));
        checkCall("failure(boom).isSuccess()", false, () -> bad.isSuccess());
        checkCall("failure(boom).valueOr(-1)", -1, () -> bad.valueOr(-1));
        checkCall("success(7).mapValue(v -> v * 2).valueOr(-1)", 14, () -> ok.mapValue(v -> v * 2).valueOr(-1));
        checkCall("failure(boom).mapValue(v -> v * 2).errorOr(?)", "boom", () -> bad.mapValue(v -> v * 2).errorOr("?"));

        int[] calls = {0};
        try {
            bad.mapValue(v -> {
                calls[0]++;
                return v;
            });
        } catch (Throwable t) {
            // the other checks already report an unfinished implementation
        }
        check("mapValue does not run f on a failure", 0, calls[0]);

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

