import java.util.function.Function;

public class TaskOutcome<T, E> {

    private final T value;
    private final E error;
    private final boolean success;

    private TaskOutcome(T value, E error, boolean success) {
        this.value = value;
        this.error = error;
        this.success = success;
    }

    public static <T, E> TaskOutcome<T, E> success(T value) {
        return new TaskOutcome<>(value, null, true);
    }

    public static <T, E> TaskOutcome<T, E> failure(E error) {
        return new TaskOutcome<>(null, error, false);
    }

    public boolean isSuccess() {
        return success;
    }

    public T valueOr(T fallback) {
        return success ? value : fallback;
    }

    public E errorOr(E fallback) {
        return success ? fallback : error;
    }

    public <R> TaskOutcome<R, E> mapValue(Function<T, R> f) {
        if (!success) {
            return TaskOutcome.failure(error);
        }
        return TaskOutcome.success(f.apply(value));
    }
}
